// Order tracking access + non-personal order summary.
//
// Tracking key: generated by the CUSTOMER's browser BEFORE the first send (120 random bits, Crockford base32,
// 24 chars). The browser keeps the key; the Worker only ever receives and stores sha256("trk1:" + key) in
// orderLedger/{id}.trackingKeyHash, written ONCE with the ledger and never changed. The Worker never returns the key,
// so a lost create response loses nothing (the browser already has it) and a third party that replays a matching
// guest payload learns nothing. No server secret: nothing to rotate, nothing whose leak exposes every order.
//
// The summary is built from an ALLOW-LIST: status, date, items (name, qty, unit price, variant label, image),
// totals, payment/shipping method and a paid flag. Never: name, phone, address, e-mail, note, CliQ reference, uid.

export const TRACKING_KEY_HASH_RE = /^[a-f0-9]{64}$/;
const KEY_RE = /^[0-9A-HJKMNP-TV-Z]{24}$/; // Crockford base32 (no I, L, O, U)
const SUMMARY_STATUSES = new Set(['new', 'processing', 'shipped', 'delivered', 'cancelled']);

/** "abcd-efgh …" -> "ABCDEFGH…" (Crockford: O->0, I/L->1), or null when it cannot be a tracking key. */
export function normalizeTrackingKey(input) {
  if (typeof input !== 'string' || input.length > 64) return null;
  const k = input.toUpperCase().replace(/[\s-]/g, '').replace(/O/g, '0').replace(/[IL]/g, '1');
  return KEY_RE.test(k) ? k : null;
}

export async function hashTrackingKey(normalizedKey) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`trk1:${normalizedKey}`));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/** constant-time comparison of two equal-format hex strings */
export function sameHex(a, b) {
  const x = String(a || '');
  const y = String(b || '');
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0 && x.length === 64;
}

const s = (v, max) => (typeof v === 'string' ? v.slice(0, max) : '');
const n = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
const httpUrl = (v) => (typeof v === 'string' && /^https?:\/\//i.test(v) && v.length <= 500 ? v : '');

/** The ONLY fields a tracking summary may contain (decoded order document -> plain object). */
export function projectSummary(id, o) {
  const raw = s(o?.status, 30);
  const date = s(o?.date, 10) || (o?.createdAt instanceof Date ? o.createdAt.toISOString().slice(0, 10) : '');
  return {
    id,
    status: SUMMARY_STATUSES.has(raw) ? raw : 'unknown',
    date,
    items: (Array.isArray(o?.items) ? o.items : []).slice(0, 50).map((it) => ({
      name: s(it?.name, 200),
      quantity: Math.max(0, Math.floor(n(it?.quantity))),
      price: n(it?.price),
      variant: s(it?.selectedVariant?.label, 80),
      image: httpUrl(it?.image),
    })),
    subtotal: n(o?.subtotal),
    discountAmount: n(o?.discountAmount),
    shippingCost: n(o?.shippingCost),
    total: n(o?.total),
    paymentMethod: o?.paymentMethod === 'cliq' ? 'cliq' : o?.paymentMethod === 'cod' ? 'cod' : '',
    shippingMethod: s(o?.shippingMethod, 200),
    paid: o?.paymentDetails?.isPaid === true,
  };
}
